def card(k):
    f,n,z=V[k];b,en,hi,mr,prod=INFO[k]
    arrow={'top':'↑','right':'→','bottom':'↓'}[z]
    return f'<div class="vc"><div class="vimg">{f()}</div><div class="vh"><b>{n}</b><span>{arrow} arrow · {prod}</span></div><div class="vb">{b}</div><div class="vt"><span class="chip">EN</span> {en}<br><span class="chip">हिन्दी</span> {hi}<br><span class="chip">मराठी</span> {mr}</div></div>'
def page(t,sub,body):return f'<div class="pg"><div class="top"><h2>{t}</h2><small>{sub}</small></div>{body}</div>'
def tbl(h,rows):return '<table class="wide"><tr>'+''.join(f'<th>{x}</th>' for x in h)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
