def hf(txt,arr=None):
    a={'up':'<path d="M280 10 L300 34 L260 34Z" fill="#FFD66B"/><rect x="140" y="0" width="280" height="5" fill="#FFD66B"/>','right':'<path d="M550 157 L526 177 L526 137Z" fill="#FFD66B"/><rect x="555" y="80" width="5" height="155" fill="#FFD66B"/>','down':'<path d="M280 305 L300 281 L260 281Z" fill="#FFD66B"/><rect x="140" y="310" width="280" height="5" fill="#FFD66B"/>',None:''}[arr]
    return f'<svg viewBox="0 0 560 315"><rect width="560" height="315" fill="#0A2A5E"/><text x="280" y="170" text-anchor="middle" font-family="P" font-weight="700" font-size="34" fill="#fff">{txt}</text>{a}</svg>'
