css=open('sb3.css').read()+'''
.vgrid{display:grid;gap:10px}.g3{grid-template-columns:1fr 1fr 1fr}.g5{grid-template-columns:repeat(5,1fr)}.g4{grid-template-columns:repeat(4,1fr)}.g6{grid-template-columns:repeat(3,1fr)}.g2{grid-template-columns:1fr 1fr}
.vc{border:1px solid #cfd8ea;border-radius:8px;padding:6px;background:#fff;min-width:0}.vimg svg{width:100%;display:block}.g5 .vimg svg{width:78%;margin:0 auto}.g6 .vimg svg{width:56%;margin:0 auto}.g3 .vimg svg{width:70%;margin:0 auto}
.vh{font-size:10px;margin:3px 0}.vh span{display:block;color:#5b6b8c;font-size:8.5px}.vb{font-size:8.5px;line-height:1.35;margin-bottom:3px}.vt{font-size:8.5px;line-height:1.5;border-top:1px solid #e3e9f5;padding-top:3px}
.cols{display:grid;grid-template-columns:1fr 1fr;gap:14px}.frs2{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin:8px 0}.frs2 svg{width:100%;border-radius:6px}
.lay{border:2px solid #0A2A5E;border-radius:8px;overflow:hidden;font-size:11px;font-weight:700;text-align:center}.lay span{font-weight:500;font-size:10px}.zt,.zb{background:#FFF4D6;padding:14px 8px}.mid{display:flex}.scr{flex:1;background:#062B57;color:#fff;padding:60px 10px;line-height:1.6}.zr{width:44%;background:#EAF1FF;padding:50px 8px}.zb{border-top:2px solid #0A2A5E}.zt{border-bottom:2px solid #0A2A5E}
.sw{display:flex;gap:6px;margin-top:8px}.sw i{width:40px;height:26px;border-radius:5px}
'''
